videoUrl.iframeSelector:
(function(){
var posted=false;
function post(v){if(!posted){posted=true;try{window.animeBridge.onLink(String(v));}catch(e){posted=false;}}}
function ok(u){u=String(u);if(u.indexOf('http')!==0){return '';}if(u.indexOf('.m3u8')>=0){return u;}if(u.indexOf('.mp4')>=0){return u;}return '';}
function extract(s){
try{
var q=s.indexOf('?');var h=s.indexOf('#');
var cut=(q>=0&&h>=0)?Math.min(q,h):((q>=0)?q:h);
if(cut<0){return '';}
var tail=s.substring(cut+1);
var m=tail.match(/https?:\/\/[^\s"'&<>]+\.m3u8/);if(m){return m[0];}
m=tail.match(/https?:\/\/[^\s"'&<>]+\.mp4/);if(m){return m[0];}
var ps=tail.split('&');
for(var i=0;i<ps.length;i++){
try{
var d=decodeURIComponent(ps[i]);
if(d!==ps[i]){
var n=d.match(/https?:\/\/[^\s"'&<>]+\.m3u8/);if(n){return n[0];}
n=d.match(/https?:\/\/[^\s"'&<>]+\.mp4/);if(n){return n[0];}
}
}catch(e){}
try{
var v=ps[i].substring(ps[i].indexOf('=')+1);
var b=atob(v);
var n2=b.match(/https?:\/\/[^\s"'&<>]+\.m3u8/);if(n2){return n2[0];}
n2=b.match(/https?:\/\/[^\s"'&<>]+\.mp4/);if(n2){return n2[0];}
}catch(e){}
}
}catch(e){}
return '';
}
var oo=XMLHttpRequest.prototype.open;
XMLHttpRequest.prototype.open=function(m,u){try{var r=ok(u);if(r){post(r);}}catch(e){}return oo.apply(this,arguments);};
var of=window.fetch;
window.fetch=function(){try{var a=arguments[0];var u=(typeof a==='string')?a:((a&&a.url)||'');var r=ok(u);if(r){post(r);}}catch(e){}return of.apply(this,arguments);};
var n=0;
var iv=setInterval(function(){
n++;
if(posted){clearInterval(iv);return;}
try{
var f=document.getElementById('hm_playfram');
var s=f?String(f.src||''):'';
if(s.indexOf('http')===0){
var p=s.split('?')[0].split('#')[0].toLowerCase();
if(p.indexOf('.m3u8')>=0||p.indexOf('.mp4')>=0){post(s);clearInterval(iv);return;}
var e1=extract(s);
if(e1){post(e1);clearInterval(iv);return;}
if(s.indexOf(location.origin)===0){
var x=new XMLHttpRequest();
x.open('GET',s);
x.onload=function(){try{var t=x.responseText;var m=t.match(/https?:\/\/[^"'\s\\<]+\.m3u8/);if(!m){m=t.match(/https?:\/\/[^"'\s\\<]+\.mp4/);}if(m){post(m[0]);}}catch(e){}};
x.send();
}
clearInterval(iv);return;
}
}catch(e){}
if(n>40){clearInterval(iv);}
},500);
return 'PENDING';
})()
